arguments.command:
cd /tmp/vally-eval-trial-FXjfWs && P=.copilot-tracking/skraft-plans/pricing && D=2026-10-09 && mkdir -p $P/features $P/details/$D $P/evidence/$D/discount tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount
cat > $P/features/checkout-pricing-loyalty-discount.feature <<'EOF'
@loyalty-discount
Feature: Loyalty tier discount at checkout
  A returning customer's loyalty tier is reflected in the checkout total.

  # SETTLED: Bronze, Silver, Gold (AC-1..AC-4). Every value below is copied from ac.md.
  # NOT DECIDED: Platinum tier. The business has agreed no reduction, so NO scenario exists for it.
  #   Escalated to DISCUSS. Do not add a Platinum example until an approved expected value exists.

  @happy-path @smoke
  Scenario Outline: Returning customer is charged the price of their loyalty tier
    Given a returning customer in the <tier> tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged <charged> cents

    Examples: AC-1, AC-2, AC-3
      | tier   | charged |
      | Bronze | 9500    |
      | Silver | 9000    |
      | Gold   | 8500    |

  @edge-case
  Scenario: Bronze customer's reduction lands on a whole cent in the customer's favour
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents
EOF
cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/LoyaltyDiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class LoyaltyDiscountAcceptanceTests
{
    // Returning customer is charged the price of their loyalty tier (AC-1, AC-2, AC-3)
    [Theory]
    [InlineData(LoyaltyTier.Bronze, 10000, 9500)]
    [InlineData(LoyaltyTier.Silver, 10000, 9000)]
    [InlineData(LoyaltyTier.Gold, 10000, 8500)]
    public void Returning_customer_is_charged_the_price_of_their_loyalty_tier(
        LoyaltyTier tier, int subtotalCents, int expectedChargedCents)
    {
        var quote = new CalculateLoyaltyDiscount().Handle(
            new CalculateLoyaltyDiscountQuery(subtotalCents, tier));

        Assert.Equal(expectedChargedCents, quote.TotalCents);
    }
}
EOF
dotnet test tests/CheckoutPricing.UnitTest --filter "FullyQualifiedName~LoyaltyDiscountAcceptanceTests" > $P/evidence/$D/discount/acceptance-red.stdout 2>&1; echo $? > $P/evidence/$D/discount/acceptance-red.exit; git rev-parse HEAD > $P/evidence/$D/discount/acceptance-red.rev; cat $P/evidence/$D/discount/acceptance-red.exit; grep -E "Assert|Expected|Actual|Failed|error" $P/evidence/$D/discount/acceptance-red.stdout | head -20

